@@ -0,0 +1,167 @@
+import type { ConfigFile, ConfigOptions, ConfigValues } from "./types.ts";
+import { ConfigParseError } from "./_errors.ts";
+
+const DEFAULT_FORMATS = [".json", ".rc"];
+
+function isMissing(error: unknown): boolean {
+  const code = (error as { code?: string })?.code;
+  const name = (error as { name?: string })?.name;
+  return code === "ENOENT" || name === "NotFound";
+}
+
+async function readTextFile(path: string): Promise<string | undefined> {
+  const global = globalThis as {
+    Deno?: { readTextFile(path: string): Promise<string> };
+  };
+  if (global.Deno) {
+    try {
+      return await global.Deno.readTextFile(path);
+    } catch (error) {
+      if (isMissing(error)) return undefined;
+      throw new ConfigParseError(path, (error as Error).message);
+    }
+  }
+  const fs = await import("node:fs/promises");
+  try {
+    return await fs.readFile(path, "utf8");
+  } catch (error) {
+    if (isMissing(error)) return undefined;
+    throw new ConfigParseError(path, (error as Error).message);
+  }
+}
+
+export function normalizeFormat(format: string): string {
+  return format.startsWith(".") ? format : "." + format;
+}
+
+export function getConfigFilename(name: string, format: string): string {
+  const extension = normalizeFormat(format);
+  return extension === ".rc" ? "." + name + "rc" : name + extension;
+}
+
+export function camelCaseKey(key: string): string {
+  return key
+    .split(".")
+    .map((part) =>
+      part.replace(
+        /-+([a-zA-Z0-9])/g,
+        (_match, char: string) => char.toUpperCase(),
+      )
+    )
+    .join(".");
+}
+
+export function flattenConfig(
+  values: ConfigValues,
+  prefix = "",
+  result: ConfigValues = {},
+): ConfigValues {
+  for (const [key, value] of Object.entries(values)) {
+    const path = camelCaseKey(prefix ? prefix + "." + key : key);
+    if (value && typeof value === "object" && !Array.isArray(value)) {
+      flattenConfig(value as ConfigValues, path, result);
+    } else {
+      result[path] = value;
+    }
+  }
+  return result;
+}
+
+function coerceRcValue(value: string): unknown {
+  if (value === "true") return true;
+  if (value === "false") return false;
+  if (/^-?(?:\d+|\d*\.\d+)$/.test(value)) return Number(value);
+  return value;
+}
+
+export function parseRc(content: string, path = ""): ConfigValues {
+  const result: ConfigValues = {};
+  for (const rawLine of content.split(/\r?\n/)) {
+    const line = rawLine.trim();
+    if (!line || line.startsWith("#")) continue;
+    const separator = line.indexOf("=");
+    if (separator === -1) {
+      throw new ConfigParseError(path, "Invalid config line: " + rawLine);
+    }
+    const key = line.slice(0, separator).trim();
+    if (!key) {
+      throw new ConfigParseError(path, "Invalid config line: " + rawLine);
+    }
+    const rawValue = line.slice(separator + 1).trim();
+    let value: unknown;
+    if (rawValue.startsWith("\"")) {
+      const end = rawValue.lastIndexOf("\"");
+      if (end <= 0) {
+        throw new ConfigParseError(path, "Unterminated quoted value: " + rawLine);
+      }
+      value = rawValue.slice(1, end);
+    } else {
+      value = coerceRcValue(rawValue);
+    }
+    result[key] = value;
+  }
+  return result;
+}
+
+export function parseJson(content: string, path = ""): ConfigValues {
+  let value: unknown;
+  try {
+    value = JSON.parse(content);
+  } catch (error) {
+    throw new ConfigParseError(path, (error as Error).message);
+  }
+  if (!value || typeof value !== "object" || Array.isArray(value)) {
+    throw new ConfigParseError(path, "Config must be an object.");
+  }
+  return value as ConfigValues;
+}
+
+export async function loadConfigFiles(
+  options: ConfigOptions,
+): Promise<{ files: ConfigFile[]; path?: string }> {
+  const searchPaths = options.searchPaths?.length ? options.searchPaths : ["."];
+  const formats = options.formats?.length ? options.formats : DEFAULT_FORMATS;
+  const files: ConfigFile[] = [];
+  for (const searchPath of searchPaths) {
+    for (const format of formats) {
+      const filename = getConfigFilename(options.name, format);
+      const path = searchPath.endsWith("/") || searchPath.endsWith("\\")
+        ? searchPath + filename
+        : searchPath + "/" + filename;
+      const content = await readTextFile(path);
+      if (content === undefined) continue;
+      let values: ConfigValues;
+      if (options.parser) {
+        try {
+          values = options.parser(content) as ConfigValues;
+        } catch (error) {
+          if (error instanceof ConfigParseError) throw error;
+          throw new ConfigParseError(path, (error as Error).message);
+        }
+      } else if (normalizeFormat(format) === ".json") {
+        values = parseJson(content, path);
+      } else if (normalizeFormat(format) === ".rc") {
+        values = parseRc(content, path);
+      } else {
+        continue;
+      }
+      if (!values || typeof values !== "object" || Array.isArray(values)) {
+        throw new ConfigParseError(path, "Config must be an object.");
+      }
+      files.push({ path, values: flattenConfig(values) });
+      break;
+    }
+    if (!options.mergeConfigs && files.length) break;
+  }
+  return { files, path: files[0]?.path };
+}
+
+export function mergeConfigValues(files: ConfigFile[]): ConfigValues {
+  const values: ConfigValues = {};
+  for (const file of files) {
+    for (const [key, value] of Object.entries(file.values)) {
+      if (!(key in values)) values[key] = value;
+    }
+  }
+  return values;
+}
