+  await reset();
+  await write(".apprc", "# c\n\nname=hello\ncount=7\nenabled=false\nzero=0\nquoted=\"hello world\"\n");
+  Deno.env.set("COUNT", "9");
+  const cmd = new Command().name("probe")
+    .option("--name <value:string>", "n")
+    .option("--count <value:number>", "c")
+    .option("--enabled", "e")
+    .option("--zero <value:number>", "z")
+    .option("--quoted <value:string>", "q")
+    .env("COUNT=<value:number>", "env")
+    .config({ name: "app", searchPaths: [dir], formats: [".rc"] })
+    .action(() => {});
+  const { options } = await cmd.parse([]);
+  assertEquals(options.name, "hello");
+  assertEquals(options.count, 9);
+  assertEquals(options.enabled, false);
+  assertEquals(options.zero, 0);
+  assertEquals(options.quoted, "hello world");
