+      .config({ name: "bad", searchPaths: [dir] })
+      .throwErrors().parse([]);
+  }, ConfigParseError);
+  await reset();
+  await write("typed.json", JSON.stringify({ enabled: "yes" }));
+  await assertRejects(async () => {
+    await new Command().name("p")
